test_that("closed-form distributions match R packages and the Python arm", {
  r <- LaplaceDist(c(-1.0, 0.2, 0.5, 2.7), loc = 0.5, scale = 1.3, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.121315874861134, 0.30535486839152, 0.384615384615385, 0.0708054617897324, 0.157710637319474, 0.396961328908976, 0.5, 0.907952899673348, -1.59226928616433, 0.5, 3.05594671328468, 1.48697395898483, -2.0613993569265, 4.95341156270497), tolerance = 1e-10)
  r <- AsyLaplace(c(-1.0, 0.1, 0.2, 2.7), loc = 0.2, scale = 1.1, kappa = 1.7, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.226721197635633, 0.520927767016937, 0.561851613936495, 0.00238031025244386, 0.299791100056487, 0.688817410778498, 0.74293059125964, 0.998910913604168, -2.45176261766981, -0.323619474139572, 0.795190897572912, 0.242985286048659, -2.92893634961644, 1.46301048503763), tolerance = 1e-10)
  r <- BurrDist(c(0.2, 1.0, 3.5), shape1 = 2.3, shape2 = 1.6, scale = 1.4, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.708493256036397, 0.471102824631223, 0.0181846350637869, 0.0951820710605925, 0.65266570084988, 0.978712552541108, 0.20675813248802, 0.728603534753473, 2.2771602378344, 1.29282225834349, 0.162599046168192, 3.8253654105696), tolerance = 1e-10)
  r <- DagumDist(c(0.2, 1.0, 3.5), shape1a = 2.5, shape2p = 0.7, scale = 1.2, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.373179675706275, 0.552039721516938, 0.0307331981335089, 0.0431327564764091, 0.515427862106039, 0.954473157816371, 0.326852599903832, 0.97239249493795, 2.90960003348588, 1.63211116490166, 0.264306064704657, 5.36138343316633), tolerance = 1e-10)
  r <- FiskDist(c(0.2, 1.0, 3.5), shape = 3.1, scale = 0.8, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.205215663128536, 0.689210643096386, 0.00894042775942183, 0.0134198115437097, 0.66635500021923, 0.989801968818743, 0.393794660006425, 0.8, 1.84277459175402, 1.1727602561571, 0.346797552145223, 3.00485070580859), tolerance = 1e-10)
  r <- FrechetDist(c(0.5, 1.0, 3.5), shape = 2.2, loc = 0.3, scale = 1.5, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(2.59333555700527e-34, 0.0799717528120462, 0.10748199682216, 2.80111700495208e-37, 0.00475802689127672, 0.827927305546212, 1.32670993424787, 2.07191678530389, 5.24227657959168, 3.03568812036763, 1.26096384661624, 10.0176851350902), tolerance = 1e-10)
  r <- GumbelDist(c(-2.0, 1.0, 5.5), loc = 1.0, scale = 2.0, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0253535568049904, 0.183939720585721, 0.0474278151385611, 0.0113142863804596, 0.367879441171442, 0.899965162660628, -0.668064890495911, 1.73302584116333, 6.24638823722604, 3.64403873386821, -0.959247837423004, 9.22132223956874), tolerance = 1e-10)
  r <- RayleighDist(c(0.2, 1.0, 3.5), sigma = 1.7, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0687268841318368, 0.291048056525124, 0.145457592365571, 0.00689652429495768, 0.158871116642392, 0.879893588018143, 0.780374128544915, 2.00159703827631, 3.92052585930401, 2.89734857541004, 0.646249138418587, 4.87923597007392), tolerance = 1e-10)
  r <- PowerDist(c(0.2, 1.0, 1.9), alpha = 2.0, beta = 3.0, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.015, 0.375, 1.35375, 0.001, 0.125, 0.857375, 0.928317766722556, 1.5874010519682, 1.95220001533702, 1.82993731689302, 0.823105460050516, 1.98909853183675), tolerance = 1e-10)
  r <- Nakagami(c(0.2, 1.0, 3.5), shape = 1.8, scale = 2.5, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0175901738046348, 0.578639125887266, 0.00456246355072609, 0.000987360045283762, 0.211233157310516, 0.999014296250525, 0.773813213346371, 1.43365133420859, 2.36229651380922, 1.87305385108147, 0.689381781890735, 2.81645755031759), tolerance = 1e-10)
  r <- Weibull3(c(0.7, 1.5, 4.5), shape = 1.7, scale = 2.0, loc = 0.5, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.166246921361609, 0.384616686848924, 0.0535936071005524, 0.0197548868673465, 0.264927469243213, 0.961187370604207, 1.03227324339349, 2.11212203437184, 4.05540676108192, 2.99096394152373, 0.92636181181266, 5.09899378301086), tolerance = 1e-10)
  r <- JohnsonSU(c(-2.0, 0.2, 3.5), gamma = 0.4, delta = 1.3, xi = 0.2, lam = 1.5, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.102981882392908, 0.319167454929547, 0.00825438279131481, 0.12945549952403, 0.655421741610324, 0.991542695700808, -2.32841446495031, -0.268855671642532, 1.58790336846576, 0.579726394221076, -2.80322792025233, 2.85821233517952), tolerance = 1e-10)
  r <- JohnsonSB(c(-0.5, 0.4, 1.7), gamma = 0.3, delta = 1.1, xi = -1.0, lam = 3.0, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.35730311590238, 0.580878245758539, 0.040550967912345, 0.0707292019197474, 0.560846391038822, 0.996705642470952, -0.424329187662776, 0.296713029384969, 1.23316354345168, 0.786666998287435, -0.502870265132187, 1.52504744118309), tolerance = 1e-10)
  r <- SinhArcsinh(c(-2.0, 0.2, 3.5), loc = 0.1, scale = 1.2, eps = 0.4, delta = 0.8, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0375155293430942, 0.264224972470427, 0.0676336594744994, 0.0207503845409836, 0.367070682601532, 0.883571695193549, -1.02082358589135, 0.725314366592497, 4.34765634283345, 2.23914825381697, -1.27003437755835, 6.52455235737598), tolerance = 1e-10)
  r <- Cardioid(c(0.3, 1.0, 5.5), mu = 1.0, rho = 0.3, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.232191991966821, 0.254647908947033, 0.139025427014446, 0.0665827853372535, 0.239509503112244, 0.862359496877212, 0.441423629459153, 2.10156136198554, 5.92497312086498, 4.54155599621637, 0.313431583191097, 6.20482740279623), tolerance = 1e-10)
  r <- CircUnif(c(0.3, 1.0, 5.5), p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.159154943091895, 0.159154943091895, 0.159154943091895, 0.0477464829275686, 0.159154943091895, 0.875352187005424, 0.628318530717959, 3.14159265358979, 5.84336233567702, 4.81280784007898, 0.437982067253977, 6.18100040253958), tolerance = 1e-10)
  r <- WrapCauchy(c(0.3, 2.0, 5.5), mu = 2.0, rho = 0.6, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0672509328381556, 0.636619772367582, 0.0410102645533491, 0.018150658238854, 0.449336106363148, 0.963741480267858, 1.09178182333423, 2.08021853201819, 4.66429704997889, 2.73486381321525, 0.876651103609085, 5.96050091644415), tolerance = 1e-10)
  r <- WrapNorm(c(0.3, 2.0, 5.5), mu = 2.0, rho = 0.6, p = c(0.1, 0.5, 0.93), n = 3, seed = 5)
  expect_equal(c(r$pdf, r$cdf, r$quantile, r$random), c(0.0959541810104283, 0.394692373287348, 0.00989262449439729, 0.0223782678241316, 0.476086069962734, 0.978766455030394, 0.831916070961395, 2.06062511200869, 3.70215203907053, 2.81474001734709, 0.667020380395625, 5.83543760793108), tolerance = 1e-10)
})

test_that("Rice, lambda and discrete distributions match references", {
  r <- RiceDist(c(0.3, 1.2, 3.1), sigma = 1.3, vee = 1.7, p = c(0.1, 0.5, 0.93))
  expect_equal(c(r$pdf, r$cdf, r$quantile), c(0.0751913285322813, 0.2758652466043360, 0.2441715259025328, 0.0113014618917644, 0.1740022716113704, 0.7825006657103627, 0.900741226929325, 2.183216098941224, 3.949005405229531), tolerance = 1e-10)
  g <- GenLambda(c(0.5, 1, 1.6), 1, 0.2, 0.13, 0.3, p = c(0.1, 0.5, 0.93))
  expect_equal(c(g$pdf, g$cdf, g$quantile), c(0.241029575395583, 0.275246511092220, 0.272854411982150, 0.228190633605884, 0.358709133054606, 0.525277092171254, -0.137879599481729, 1.507895269365825, 3.701408470725271), tolerance = 1e-10)
  expect_equal(TukeyLambda(0.25, lam = 1)$cdf, 0.625)
  o <- OrderedLogis(c(0, 2, 3), eta = 0.3, cuts = c(-1, 0.5, 2))
  expect_equal(o$pmf, c(plogis(-1.3), plogis(1.7) - plogis(0.2), 1 - plogis(1.7)), tolerance = 1e-14)
  expect_equal(CategoricalDist(0:2, probs = c(1, 2, 5))$pmf, c(0.125, 0.25, 0.625))
  skip_if_not_installed("extraDistr")
  expect_equal(LaplaceDist(c(-1, 2), 0.5, 1.3)$pdf, extraDistr::dlaplace(c(-1, 2), 0.5, 1.3), tolerance = 1e-12)
  expect_equal(BurrDist(1:3, shape1 = 2.3, shape2 = 1.6, scale = 1.4)$cdf, 1 - (1 + ((1:3) / 1.4)^1.6)^(-2.3), tolerance = 1e-12)
})
